public class UserSession implements Serializable {
    private String username;
    private transient String passwordHash; // Excluded from serialization!
    private transient Socket connection;   // Excluded!
}

public class UserProfile implements Serializable {
    // Explicit serialVersionUID prevents accidental incompatibility:
    private static final long serialVersionUID = 1L;

    private String email;
}

public class Elvis implements Serializable {
    public static final Elvis INSTANCE = new Elvis();
    private Elvis() {}

    // Guarantees singleton identity across serialization:
    private Object readResolve() {
        return INSTANCE;
    }
}

public enum Operation {
    PLUS {
        public double apply(double x, double y) { return x + y; }
    },
    MINUS {
        public double apply(double x, double y) { return x - y; }
    };

    public abstract double apply(double x, double y);
}

